/**
 * CLUBS-35: write-ups are generated by the Poll, never by a page. A Session
 * that is over gets one call writing its recap, its Match reports and the
 * State of the club, against the fake Anthropic upstream.
 */
import { AI_MODEL, MODEL_PRICES } from "../app/ai/config.ts";
import { FAKE_USAGE } from "./fake-anthropic/control.ts";
import { expect, test } from "./support/test.ts";
import {
  type AiJobRow,
  type AiWriteupRow,
  KAB,
  type PollRunRow,
  serveSession,
  TREV,
} from "./support/writeups.ts";

/** Every text block of a request's messages, as the model reads them. */
function promptText(body: Record<string, unknown>): string {
  const messages = body.messages as { content: { text?: string }[] }[];
  return messages
    .flatMap((m) => m.content.map((block) => block.text ?? ""))
    .join("\n");
}

test.beforeEach(async ({ fakeEa }) => {
  // Only the Matches each test adds.
  await fakeEa.setPayload("clubs/matches", [], "leagueMatch");
});

test("a Session over for 45 minutes gets one call: its recap, a report per Match and the State of the club", async ({
  fakeEa,
  fakeAnthropic,
  triggerPoll,
  db,
}) => {
  const ids = await serveSession(fakeEa, {
    idPrefix: "93510000000000",
    startedMinutesAgo: 120,
    results: ["W", "L"],
  });
  await triggerPoll();

  const requests = await fakeAnthropic.requests();
  expect(requests).toHaveLength(1);
  const [{ body, raw }] = requests;
  expect(body.model).toBe(AI_MODEL);
  // Pre-computed per-player Appearance stats for both clubs...
  const prompt = promptText(body);
  for (const text of [
    `"name":"${KAB.name}"`,
    `"name":"${TREV.name}"`,
    '"club":"A Bloo Bloo"',
    '"shots":4',
    '"tackles":',
    '"passes":',
    '"rating":"8.4"',
  ]) {
    expect(prompt).toContain(text);
  }
  // ...never EA's Raw Payloads.
  for (const eaField of ["vproattr", "passattempts", "match_event_aggregate"]) {
    expect(raw).not.toContain(eaField);
  }

  const writeups = await db.rows<AiWriteupRow>("ai_writeups");
  expect(writeups.map((w) => [w.kind, w.subject_key])).toEqual([
    ["session", ids[0]],
    ["match", ids[0]],
    ["headline", ids[0]],
    ["match", ids[1]],
    ["headline", ids[1]],
    ["club", "club"],
  ]);

  const [job] = await db.rows<AiJobRow>("ai_jobs");
  const price = MODEL_PRICES[AI_MODEL];
  expect(job).toMatchObject({
    kind: "session",
    subject_key: ids[0],
    version: ids.join(","),
    status: "done",
    attempts: 1,
    model: AI_MODEL,
    input_tokens: FAKE_USAGE.input_tokens,
    output_tokens: FAKE_USAGE.output_tokens,
    cache_write_tokens: FAKE_USAGE.cache_creation_input_tokens,
    cache_read_tokens: 0,
  });
  expect(job.cost_usd).toBeCloseTo(
    (FAKE_USAGE.input_tokens * price.input +
      FAKE_USAGE.output_tokens * price.output +
      FAKE_USAGE.cache_creation_input_tokens * price.cacheWrite) /
      1_000_000,
  );
  // The input is kept for auditing, with its hash.
  expect(JSON.parse(job.input ?? "")).toEqual(body);
  expect(job.input_hash).toMatch(/^[0-9a-f]{64}$/);
});

test("a long Session's recap and all its Match reports are stored, past D1's 100-parameter cap", async ({
  fakeEa,
  triggerPoll,
  db,
}) => {
  // 22 Matches, 30 minutes apart; EA serves 10 a Poll, so they arrive in three.
  const chunks = [
    { idPrefix: "93517000000000", startedMinutesAgo: 700, count: 10 },
    { idPrefix: "93517100000000", startedMinutesAgo: 400, count: 10 },
    { idPrefix: "93517200000000", startedMinutesAgo: 100, count: 2 },
  ];
  const ids: string[] = [];
  for (const { idPrefix, startedMinutesAgo, count } of chunks) {
    ids.push(
      ...(await serveSession(fakeEa, {
        idPrefix,
        startedMinutesAgo,
        results: Array(count).fill("W"),
      })),
    );
    await triggerPoll();
  }

  const jobs = await db.rows<AiJobRow>("ai_jobs");
  const latest = jobs.at(-1);
  expect(latest).toMatchObject({ version: ids.join(","), status: "done" });
  const written = (await db.rows<AiWriteupRow>("ai_writeups")).filter(
    (w) => w.job_id === latest?.id,
  );
  // The recap, 22 Match reports and headlines, and the State of the club.
  expect(written).toHaveLength(46);
});

test("a Session still within 45 minutes of its last kick-off gets no call yet", async ({
  fakeEa,
  fakeAnthropic,
  triggerPoll,
}) => {
  await serveSession(fakeEa, {
    idPrefix: "93511000000000",
    startedMinutesAgo: 40,
    results: ["W", "W"],
  });
  await triggerPoll();
  expect(await fakeAnthropic.requests()).toHaveLength(0);
});

test("a further Poll with no new Matches makes no new call", async ({
  fakeEa,
  fakeAnthropic,
  triggerPoll,
  db,
}) => {
  await serveSession(fakeEa, {
    idPrefix: "93512000000000",
    startedMinutesAgo: 120,
    results: ["W", "D"],
  });
  await triggerPoll();
  await triggerPoll();
  await triggerPoll();
  expect(await fakeAnthropic.requests()).toHaveLength(1);
  expect(await db.rows("ai_jobs")).toHaveLength(1);
  expect(await db.rows("ai_writeups")).toHaveLength(6);
});

test("a Match added to a finished Session rewrites that Session's recap only", async ({
  fakeEa,
  fakeAnthropic,
  triggerPoll,
  db,
}) => {
  // An older Session, ended, and a newer one, ended.
  const older = await serveSession(fakeEa, {
    idPrefix: "93513000000000",
    startedMinutesAgo: 300,
    results: ["W", "L"],
  });
  const newer = await serveSession(fakeEa, {
    idPrefix: "93513100000000",
    startedMinutesAgo: 120,
    results: ["D"],
  });
  await triggerPoll();
  expect(await fakeAnthropic.requests()).toHaveLength(2);

  // EA reports a late Match, 30 minutes after the older Session's last.
  const [late] = await serveSession(fakeEa, {
    idPrefix: "93513200000000",
    startedMinutesAgo: 240,
    results: ["W"],
  });
  await triggerPoll();

  const requests = await fakeAnthropic.requests();
  expect(requests).toHaveLength(3);
  const rewritten = promptText(requests[2].body);
  expect(rewritten).toContain(`"matchId":"${late}"`);
  expect(rewritten).not.toContain(newer[0]);

  const jobs = await db.rows<AiJobRow>("ai_jobs");
  expect(jobs.map((j) => [j.subject_key, j.version])).toEqual([
    [newer[0], newer[0]],
    [older[0], older.join(",")],
    [older[0], [...older, late].join(",")],
  ]);
  // The rewrite covers the late Match, and only the newer Session wrote the State of the club.
  const writeups = await db.rows<AiWriteupRow>("ai_writeups");
  const rewrite = writeups.filter((w) => w.job_id === jobs[2].id);
  expect(rewrite.map((w) => [w.kind, w.subject_key])).toEqual([
    ["session", older[0]],
    ["match", older[0]],
    ["headline", older[0]],
    ["match", older[1]],
    ["headline", older[1]],
    ["match", late],
    ["headline", late],
  ]);
});

test("a failing API (500 or timeout) leaves the Poll ok and is retried on later Polls, 3 times at most", async ({
  fakeEa,
  fakeAnthropic,
  triggerPoll,
  db,
}) => {
  const [sessionId] = await serveSession(fakeEa, {
    idPrefix: "93514000000000",
    startedMinutesAgo: 120,
    results: ["W"],
  });
  await fakeAnthropic.failNext(500);
  await fakeAnthropic.timeoutNext();
  await fakeAnthropic.failNext(529, { type: "overloaded_error" });

  for (let poll = 1; poll <= 4; poll++) await triggerPoll();

  // Three attempts, then it stops.
  expect(await fakeAnthropic.requests()).toHaveLength(3);
  const runs = await db.rows<PollRunRow>("poll_runs");
  expect(runs.map((r) => r.status)).toEqual(["ok", "ok", "ok", "ok"]);
  const [job] = await db.rows<AiJobRow>("ai_jobs");
  expect(job).toMatchObject({
    subject_key: sessionId,
    status: "failed",
    attempts: 3,
  });
  expect(job.last_error).toContain("529");
  expect(await db.rows("ai_writeups")).toHaveLength(0);
});

test("a failed call is written on the next Poll", async ({
  fakeEa,
  fakeAnthropic,
  triggerPoll,
  db,
}) => {
  await serveSession(fakeEa, {
    idPrefix: "93515000000000",
    startedMinutesAgo: 120,
    results: ["W"],
  });
  await fakeAnthropic.timeoutNext();
  await triggerPoll();
  expect(await db.rows("ai_writeups")).toHaveLength(0);

  await triggerPoll();
  expect(await fakeAnthropic.requests()).toHaveLength(2);
  const [job] = await db.rows<AiJobRow>("ai_jobs");
  expect(job).toMatchObject({ status: "done", attempts: 2 });
  expect(await db.rows("ai_writeups")).toHaveLength(4);
});

test("backfill: past Sessions are written a few per Poll, newest first, once each", async ({
  fakeEa,
  fakeAnthropic,
  triggerPoll,
  db,
}) => {
  const sessions = [
    await serveSession(fakeEa, {
      idPrefix: "93516000000000",
      startedMinutesAgo: 3 * 24 * 60,
      results: ["W", "D"],
    }),
    await serveSession(fakeEa, {
      idPrefix: "93516100000000",
      startedMinutesAgo: 2 * 24 * 60,
      results: ["L"],
    }),
    await serveSession(fakeEa, {
      idPrefix: "93516200000000",
      startedMinutesAgo: 24 * 60,
      results: ["W", "W", "L"],
    }),
  ];
  const [oldest, middle, newest] = sessions;

  await triggerPoll();
  const jobs = await db.rows<AiJobRow>("ai_jobs");
  expect(jobs.map((j) => j.subject_key)).toEqual([newest[0], middle[0]]);

  await triggerPoll();
  await triggerPoll();
  expect(await fakeAnthropic.requests()).toHaveLength(3);

  const writeups = await db.rows<AiWriteupRow>("ai_writeups");
  const keys = (kind: string) =>
    writeups.filter((w) => w.kind === kind).map((w) => w.subject_key);
  expect(keys("session")).toEqual([newest[0], middle[0], oldest[0]]);
  expect(keys("match").sort()).toEqual(sessions.flat().sort());
  // Only the newest Session's call writes the State of the club.
  expect(keys("club")).toEqual(["club"]);
  expect(writeups.find((w) => w.kind === "club")?.job_id).toBe(jobs[0].id);
});
